settings.custom_liquid:
{%- liquid
  assign nur_fr = false
  if request.locale.iso_code == 'fr'
    assign nur_fr = true
  endif
  assign nur_root = routes.root_url
  if nur_root == '/'
    assign nur_root = ''
  endif
-%}
<!-- ============================================
     NUR PROTOCOL — REVIEWS / TESTIMONIALS PAGE
     12 real tester verbatims (source: Nur Protocol Verbatim file
     provided by the user). French verbatims translated to English
     for site consistency, meaning preserved faithfully. No star
     ratings invented — only Sara Hassan's explicit "4 stars" is
     reflected in her own quote text. Order interleaves gender,
     cultural background and language of origin so no block of
     similar names reads as a cluster.
     ============================================ -->

<style>
  .nur-reviews {
    font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
    background-color: #FAFAF8;
  }

  .nur-reviews__hero {
    max-width: 680px;
    margin: 0 auto;
    text-align: center;
    padding: 100px 40px 72px;
  }

  .nur-reviews__eyebrow {
    display: inline-block;
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 4px;
    text-transform: uppercase;
    color: #C8A96E;
    margin-bottom: 20px;
  }

  .nur-reviews__title {
    font-size: clamp(28px, 3.8vw, 46px);
    font-weight: 300;
    line-height: 1.18;
    color: #1A1A1A;
    margin: 0 0 20px;
    letter-spacing: -0.5px;
  }

  .nur-reviews__title em {
    font-style: italic;
    color: #C8A96E;
  }

  .nur-reviews__lead {
    font-size: 15px;
    font-weight: 400;
    line-height: 1.75;
    color: #8A8A8A;
    margin: 0;
  }

  .nur-reviews__grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 28px;
    max-width: 1280px;
    margin: 0 auto;
    padding: 0 40px 48px;
  }

  .nur-reviews__card {
    background-color: #FFFFFF;
    box-shadow: 0 0 0 1px rgba(200,169,110,0.2);
    padding: 32px 28px;
    display: flex;
    flex-direction: column;
  }


  .nur-reviews__stars {
    display: flex;
    gap: 2px;
    margin: 0 0 14px;
  }

  .nur-reviews__star {
    width: 13px;
    height: 13px;
    fill: #C8A96E;
    stroke: none;
  }

  .nur-reviews__star--empty {
    fill: #E3DFD5;
  }

  .nur-reviews__card-title {
    font-size: 15px;
    font-weight: 600;
    color: #1A1A1A;
    margin: 0 0 12px;
    letter-spacing: -0.1px;
  }

  .nur-reviews__card-text {
    font-size: 13px;
    font-weight: 400;
    line-height: 1.7;
    color: #5A5A5A;
    margin: 0 0 20px;
    flex-grow: 1;
  }

  .nur-reviews__card-footer {
    display: flex;
    align-items: center;
    gap: 10px;
    padding-top: 16px;
    border-top: 1px solid rgba(200,169,110,0.2);
  }

    .nur-reviews__name {
    font-size: 12.5px;
    font-weight: 500;
    color: #1A1A1A;
  }

  .nur-reviews__note {
    text-align: center;
    max-width: 560px;
    margin: 0 auto 100px;
    padding: 0 40px;
  }

  .nur-reviews__note p {
    font-size: 12px;
    font-weight: 400;
    color: #A0A0A0;
    line-height: 1.7;
    margin: 0;
    font-style: italic;
  }

  @media (max-width: 1024px) {
    .nur-reviews__grid { grid-template-columns: repeat(2, 1fr); }
  }

  @media (max-width: 640px) {
    .nur-reviews__hero { padding: 64px 20px 48px; }
    .nur-reviews__grid { grid-template-columns: 1fr; padding: 0 20px 72px; gap: 20px; }
    .nur-reviews__note { margin-top: -48px; margin-bottom: 64px; padding: 0 20px; }
  }
</style>

<div class="nur-reviews">

  <section class="nur-reviews__hero">
    <span class="nur-reviews__eyebrow">{% if nur_fr %}Vrais testeurs{% else %}Real Testers{% endif %}</span>
    <h1 class="nur-reviews__title">{% if nur_fr %}Ce qu’ils nous disent<br><em>avec leurs propres mots</em>{% else %}What they're telling us<br><em>in their own words</em>{% endif %}</h1>
    <p class="nur-reviews__lead">{% if nur_fr %}Les retours des premiers testeurs NŪR Protocol, sans filtre : les élogieux comme les plus nuancés.{% else %}Unedited feedback from early NŪR Protocol testers, good and mixed alike.{% endif %}</p>
  </section>

  <div class="nur-reviews__grid">

    <div class="nur-reviews__card">
      <div class="nur-reviews__stars"><svg class="nur-reviews__star" viewBox="0 0 20 20"><polygon points="10,1.5 12.6,7 18.5,7.6 14,11.8 15.3,17.5 10,14.5 4.7,17.5 6,11.8 1.5,7.6 7.4,7"/></svg><svg class="nur-reviews__star" viewBox="0 0 20 20"><polygon points="10,1.5 12.6,7 18.5,7.6 14,11.8 15.3,17.5 10,14.5 4.7,17.5 6,11.8 1.5,7.6 7.4,7"/></svg><svg class="nur-reviews__star" viewBox="0 0 20 20"><polygon points="10,1.5 12.6,7 18.5,7.6 14,11.8 15.3,17.5 10,14.5 4.7,17.5 6,11.8 1.5,7.6 7.4,7"/></svg><svg class="nur-reviews__star" viewBox="0 0 20 20"><polygon points="10,1.5 12.6,7 18.5,7.6 14,11.8 15.3,17.5 10,14.5 4.7,17.5 6,11.8 1.5,7.6 7.4,7"/></svg><svg class="nur-reviews__star" viewBox="0 0 20 20"><polygon points="10,1.5 12.6,7 18.5,7.6 14,11.8 15.3,17.5 10,14.5 4.7,17.5 6,11.8 1.5,7.6 7.4,7"/></svg></div>
      <h3 class="nur-reviews__card-title">{% if nur_fr %}Excellent produit et concept très astucieux{% else %}Great product and a very clever concept{% endif %}</h3>
      <p class="nur-reviews__card-text">{% if nur_fr %}Tout s’est parfaitement passé et je suis vraiment content du produit. C’est l’association du masque LED et du Skin Coach IA qui fait la différence pour moi. C’est très pratique d’avoir un accompagnement directement dans l’application au lieu de devoir construire sa routine soi-même. Une approche du soin de la peau très intéressante et innovante.{% else %}Everything went perfectly and I'm really happy with the product. The combination of the LED mask and the AI Skin Coach is what makes it stand out for me. It's really convenient to have guidance directly in the app instead of having to figure out your routine yourself. A very interesting and innovative approach to skincare.{% endif %}</p>
      <div class="nur-reviews__card-footer">
        <span class="nur-reviews__name">Michael Thompson</span>
      </div>
    </div>

    <div class="nur-reviews__card">
      <div class="nur-reviews__stars"><svg class="nur-reviews__star" viewBox="0 0 20 20"><polygon points="10,1.5 12.6,7 18.5,7.6 14,11.8 15.3,17.5 10,14.5 4.7,17.5 6,11.8 1.5,7.6 7.4,7"/></svg><svg class="nur-reviews__star" viewBox="0 0 20 20"><polygon points="10,1.5 12.6,7 18.5,7.6 14,11.8 15.3,17.5 10,14.5 4.7,17.5 6,11.8 1.5,7.6 7.4,7"/></svg><svg class="nur-reviews__star" viewBox="0 0 20 20"><polygon points="10,1.5 12.6,7 18.5,7.6 14,11.8 15.3,17.5 10,14.5 4.7,17.5 6,11.8 1.5,7.6 7.4,7"/></svg><svg class="nur-reviews__star" viewBox="0 0 20 20"><polygon points="10,1.5 12.6,7 18.5,7.6 14,11.8 15.3,17.5 10,14.5 4.7,17.5 6,11.8 1.5,7.6 7.4,7"/></svg><svg class="nur-reviews__star" viewBox="0 0 20 20"><polygon points="10,1.5 12.6,7 18.5,7.6 14,11.8 15.3,17.5 10,14.5 4.7,17.5 6,11.8 1.5,7.6 7.4,7"/></svg></div>
      <h3 class="nur-reviews__card-title">{% if nur_fr %}J’ai 52 ans et je suis vraiment impressionnée par les résultats{% else %}I'm 52 and really impressed with the results{% endif %}</h3>
      <p class="nur-reviews__card-text">{% if nur_fr %}J’utilise Nur Protocol depuis environ cinq semaines. Mon teint est plus net et plus uniforme, et les petites imperfections que j’avais ont presque disparu. Je vois aussi une vraie amélioration de mes ridules, même si je n’ai pas encore remarqué beaucoup de changement sur les rides plus profondes. Ce que j’adore, c’est Nur AI : je n’ai plus à me demander sans cesse ce dont ma peau a besoin. J’utilise le masque une fois par semaine et je vais clairement continuer.{% else %}I've been using Nur Protocol for about five weeks now. My complexion looks clearer and more even, and the little imperfections I had have almost disappeared. I can also see a real improvement in my fine lines, although I haven't noticed much change yet on deeper wrinkles. What I really love is Nur AI: I don't have to constantly wonder what my skin needs. I use the mask once a week and I'm definitely going to keep going.{% endif %}</p>
      <div class="nur-reviews__card-footer">
        <span class="nur-reviews__name">Aisha Al-Mansouri</span>
      </div>
    </div>

    <div class="nur-reviews__card">
      <div class="nur-reviews__stars"><svg class="nur-reviews__star" viewBox="0 0 20 20"><polygon points="10,1.5 12.6,7 18.5,7.6 14,11.8 15.3,17.5 10,14.5 4.7,17.5 6,11.8 1.5,7.6 7.4,7"/></svg><svg class="nur-reviews__star" viewBox="0 0 20 20"><polygon points="10,1.5 12.6,7 18.5,7.6 14,11.8 15.3,17.5 10,14.5 4.7,17.5 6,11.8 1.5,7.6 7.4,7"/></svg><svg class="nur-reviews__star" viewBox="0 0 20 20"><polygon points="10,1.5 12.6,7 18.5,7.6 14,11.8 15.3,17.5 10,14.5 4.7,17.5 6,11.8 1.5,7.6 7.4,7"/></svg><svg class="nur-reviews__star" viewBox="0 0 20 20"><polygon points="10,1.5 12.6,7 18.5,7.6 14,11.8 15.3,17.5 10,14.5 4.7,17.5 6,11.8 1.5,7.6 7.4,7"/></svg><svg class="nur-reviews__star" viewBox="0 0 20 20"><polygon points="10,1.5 12.6,7 18.5,7.6 14,11.8 15.3,17.5 10,14.5 4.7,17.5 6,11.8 1.5,7.6 7.4,7"/></svg></div>
      <h3 class="nur-reviews__card-title"{% if nur_fr %}>Des résultats encourageants<{% else %}>Encouraging results<{% endif %}/h3>
      <p class="nur-reviews__card-text">{% if nur_fr %}Je suis agréablement surprise par les premiers résultats. Ma peau est plus nette et plus lumineuse après seulement quelques utilisations. J’adore aussi le concept de Nur Skin Coach AI : avoir un protocole adapté à sa propre peau évite de devoir deviner seule ce qui pourrait fonctionner. C’est vraiment rassurant et bien plus facile à intégrer dans une routine.{% else %}I'm pleasantly surprised by the first results. My skin looks clearer and brighter after just a few uses. I also really love the Nur Skin Coach AI concept: having a protocol adapted to your own skin means you don't have to figure out what might work on your own. It's genuinely reassuring and much easier to fit into a routine.{% endif %}</p>
      <div class="nur-reviews__card-footer">
        <span class="nur-reviews__name">Claire Moreau</span>
      </div>
    </div>

    <div class="nur-reviews__card">
      <div class="nur-reviews__stars"><svg class="nur-reviews__star" viewBox="0 0 20 20"><polygon points="10,1.5 12.6,7 18.5,7.6 14,11.8 15.3,17.5 10,14.5 4.7,17.5 6,11.8 1.5,7.6 7.4,7"/></svg><svg class="nur-reviews__star" viewBox="0 0 20 20"><polygon points="10,1.5 12.6,7 18.5,7.6 14,11.8 15.3,17.5 10,14.5 4.7,17.5 6,11.8 1.5,7.6 7.4,7"/></svg><svg class="nur-reviews__star" viewBox="0 0 20 20"><polygon points="10,1.5 12.6,7 18.5,7.6 14,11.8 15.3,17.5 10,14.5 4.7,17.5 6,11.8 1.5,7.6 7.4,7"/></svg><svg class="nur-reviews__star" viewBox="0 0 20 20"><polygon points="10,1.5 12.6,7 18.5,7.6 14,11.8 15.3,17.5 10,14.5 4.7,17.5 6,11.8 1.5,7.6 7.4,7"/></svg><svg class="nur-reviews__star nur-reviews__star--empty" viewBox="0 0 20 20"><polygon points="10,1.5 12.6,7 18.5,7.6 14,11.8 15.3,17.5 10,14.5 4.7,17.5 6,11.8 1.5,7.6 7.4,7"/></svg></div>
      <h3 class="nur-reviews__card-title">{% if nur_fr %}Très bien, et j’adore l’approche personnalisée{% else %}Very good, and I love the personalised approach{% endif %}</h3>
      <p class="nur-reviews__card-text">{% if nur_fr %}Je suis vraiment contente du masque jusqu’ici. Il est facile à utiliser et j’aime particulièrement que Skin Coach AI vous donne un protocole basé sur votre propre peau plutôt que la même routine pour tout le monde. Cette approche personnalisée fait une vraie différence. La seule raison pour laquelle je mets 4 étoiles, c’est le prix, que je trouve assez élevé.{% else %}I'm really happy with the mask so far. It's easy to use and I particularly like that Skin Coach AI gives you a protocol based on your own skin rather than the same routine for everyone. That personalised approach makes a real difference. The only reason I'm giving 4 stars is the price, which I find quite high.{% endif %}</p>
      <div class="nur-reviews__card-footer">
        <span class="nur-reviews__name">Sara Hassan</span>
      </div>
