      <div class="nur-reviews__stars"><svg class="nur-reviews__star" viewBox="0 0 20 20"><polygon points="10,1.5 12.6,7 18.5,7.6 14,11.8 15.3,17.5 10,14.5 4.7,17.5 6,11.8 1.5,7.6 7.4,7"/></svg><svg class="nur-reviews__star" viewBox="0 0 20 20"><polygon points="10,1.5 12.6,7 18.5,7.6 14,11.8 15.3,17.5 10,14.5 4.7,17.5 6,11.8 1.5,7.6 7.4,7"/></svg><svg class="nur-reviews__star" viewBox="0 0 20 20"><polygon points="10,1.5 12.6,7 18.5,7.6 14,11.8 15.3,17.5 10,14.5 4.7,17.5 6,11.8 1.5,7.6 7.4,7"/></svg><svg class="nur-reviews__star" viewBox="0 0 20 20"><polygon points="10,1.5 12.6,7 18.5,7.6 14,11.8 15.3,17.5 10,14.5 4.7,17.5 6,11.8 1.5,7.6 7.4,7"/></svg><svg class="nur-reviews__star" viewBox="0 0 20 20"><polygon points="10,1.5 12.6,7 18.5,7.6 14,11.8 15.3,17.5 10,14.5 4.7,17.5 6,11.8 1.5,7.6 7.4,7"/></svg></div>
